window.WB_BOOK=window.WB_BOOK||{};window.WB_BOOK["week13"]={"id":"week13","n":15,"section":"X","label":"Mock Exam 1","title":"Mock Paper 02 (Full Exam) + Review","titleText":"Mock Paper 02 (Full Exam) + Review","subtitle":"One complete, original Paper 02 in exact CSEC format — sit it timed, then learn from every lost mark","intro":"This book is different from the others. It is not a new topic. It is a **full practice Paper 02** — the long, written paper you sit on **Tuesday 5 January 2027**. The paper is in the Past-Paper Practice section (PP1–PP6). It has six compulsory questions, covers all five sections of the syllabus, and is marked out of 100, exactly like the real exam. Before you sit it, read Unit 13.2 (exam technique). After your tutor marks it, use Unit 13.1 to review every lost mark and turn it into a plan. A mock is not a verdict on you — it is a map that shows exactly where your next marks will come from.","objectives":[{"code":"A","text":"Section A — Mechanics: scientific method and measurement, graph skills, vectors, forces and moments, motion and momentum, energy and power, hydrostatics"},{"code":"B","text":"Section B — Thermal physics and kinetic theory: temperature, gas laws, specific heat capacity, latent heat, heat transfer"},{"code":"C","text":"Section C — Waves and optics: wave properties, sound, the electromagnetic spectrum, reflection, refraction, total internal reflection, lenses"},{"code":"D","text":"Section D — Electricity and magnetism: static charge, current and circuits, mains electricity, electronics, magnetism, electromagnetism and transformers"},{"code":"E","text":"Section E — The physics of the atom: models of the atom, atomic structure, radioactivity, half-life, nuclear energy"}],"formulaCard":[{"tex":"\\text{gradient }=\\Delta y\\div \\Delta x","meaning":"From a large triangle on the line; unit ⟪=y⟫-unit ÷ x-unit","units":"—"},{"tex":"V=IR","meaning":"p.d. = current × resistance (gradient of V–I graph ⟪=R⟫)","units":"V, A, Ω"},{"tex":"P=IV\\qquad E=Pt","meaning":"Electrical power; energy = power × time","units":"W, J (or kWh with kW and h)"},{"tex":"\\text{cost }=\\mathrm{kWh}\\times \\text{ price per }\\mathrm{kWh}","meaning":"⟪\\mathrm{kWh}=\\mathrm{kW}⟫ × hours","units":"$"},{"tex":"V_{p}/V_{s}=N_{p}/N_{s}\\qquad V_{p}I_{p}=V_{s}I_{s}","meaning":"Ideal transformer: voltage ratio = turns ratio; power in = power out","units":"V, turns, A"},{"tex":"E_{H}=mc\\Delta \\theta","meaning":"Heat to change temperature; Δθ = temperature RISE","units":"J, kg, J kg^−1^ K^−1^, K"},{"tex":"E_{H}=ml","meaning":"Heat to change state (no temperature change)","units":"J, kg, J kg^−1^"},{"tex":"p_{1}/T_{1}=p_{2}/T_{2}\\qquad (pV/T=\\text{ constant})","meaning":"Gas laws — T must be in kelvin: ⟪K={}^{\\circ}\\mathrm{C}+273⟫","units":"Pa, m^3^, K"},{"tex":"v=f\\lambda \\qquad T=1/f","meaning":"Wave speed = frequency × wavelength; period ⟪=1⟫ ÷ frequency","units":"m s^−1^, Hz, m, s"},{"tex":"\\text{distance }=\\text{ speed }\\times \\text{ time }(\\text{echo: }\\div 2)","meaning":"Echo travels there AND back","units":"m, m s^−1^, s"},{"tex":"n=\\sin i\\div \\sin r\\qquad \\sin c=1/n","meaning":"Refractive index; critical angle (angles from the normal)","units":"no unit"},{"tex":"p=mv\\text{ total }p\\text{ before }=\\text{ total }p\\text{ after}","meaning":"Momentum and its conservation (closed system)","units":"kg m s^−1^"},{"tex":"F=ma\\qquad a=(v-u)/t","meaning":"Newton's second law; acceleration","units":"N, kg, m s^−2^"},{"tex":"E_{k}=\\tfrac{1}{2}mv^{2}\\qquad \\Delta E_{p}=mg\\Delta h","meaning":"Kinetic and gravitational potential energy ⟪(g=10\\,\\mathrm{N}\\,\\mathrm{kg}^{-1})⟫","units":"J"},{"tex":"A=Z+N;\\quad \\alpha ={}^{4}_{2}\\text{He}","meaning":"Nucleon number = protons + neutrons; balance A and Z in decay equations","units":"—"},{"tex":"\\text{after }n\\text{ half-lives: amount }\\times (\\tfrac{1}{2})^{n}","meaning":"Halve once for every half-life","units":"same as start"},{"tex":"1\\tfrac{1}{2}\\text{ min per mark}","meaning":"Paper 02 timing: ⟪Q1\\approx 35\\,\\mathrm{min}⟫, each 15-mark question ≈ 20–22 min","units":"min"}],"glossary":[{"term":"State","def":"Give a short answer with no explanation."},{"term":"Define","def":"Give the precise meaning of a term in words, with the key words."},{"term":"Describe","def":"Say what happens or what is done, step by step."},{"term":"Explain","def":"Give reasons using physics ideas (\"because… so…\")."},{"term":"Calculate","def":"Work out a numerical answer, showing working and units."},{"term":"Determine","def":"Find a value, often from a graph or data, showing the method."},{"term":"Deduce","def":"Draw a conclusion from the information given or worked out."},{"term":"Sketch","def":"A quick graph or diagram showing shape and key features, not to scale."},{"term":"Plot","def":"Mark points accurately on a grid using a chosen scale."},{"term":"Suggest","def":"Use physics to propose a sensible answer; more than one may be correct."},{"term":"Anomalous result","def":"A reading that does not fit the pattern of the others; circle and ignore it."},{"term":"Interpolation","def":"Reading a value from a graph between plotted points."},{"term":"Extrapolation","def":"Extending a graph line beyond the plotted points (draw it dashed)."},{"term":"Precaution","def":"A step taken to make readings more accurate or reliable, specific to the experiment."},{"term":"Error carried forward (ECF)","def":"Marks given for correctly using a wrong earlier answer — only if working is shown."},{"term":"Mark scheme","def":"The list of points the examiner gives marks for; about one point per mark."}],"studyPlan":[["Day 1","Read Unit 13.2 (exam technique). Do the 13.2 practice questions. Re-read your formula cards from Weeks 1–12.","45 min",""],["Day 2 (or 3)","SIT THE MOCK (PP1–PP6) in ONE sitting: 2 h 30 min, timed, quiet room, no notes, calculator allowed. Follow the timing plan.","150 min",""],["Before session","Hand in / send photos of the whole paper to your tutor for marking. Do NOT look at answers yet.","5 min",""],["After session","Unit 13.1: fill in the score table and error tally; write corrections in a different colour; plan your redo.","30 min",""],["Every day","Flash cards: the formula card at the back of this book","5–10 min",""]],"lessons":[{"id":"week13.13.2","kind":"unit","unit":"13.2","title":"Exam Technique for Paper 02","titleText":"Exam Technique for Paper 02","goals":[{"code":"A","text":"Section A — Mechanics: scientific method and measurement, graph skills, vectors, forces and moments, motion and momentum, energy and power, hydrostatics"},{"code":"B","text":"Section B — Thermal physics and kinetic theory: temperature, gas laws, specific heat capacity, latent heat, heat transfer"},{"code":"C","text":"Section C — Waves and optics: wave properties, sound, the electromagnetic spectrum, reflection, refraction, total internal reflection, lenses"},{"code":"D","text":"Section D — Electricity and magnetism: static charge, current and circuits, mains electricity, electronics, magnetism, electromagnetism and transformers"},{"code":"E","text":"Section E — The physics of the atom: models of the atom, atomic structure, radioactivity, half-life, nuclear energy"}],"codes":["A","B","C","D","E"],"words":[{"term":"State","def":"Give a short answer with no explanation."},{"term":"Define","def":"Give the precise meaning of a term in words, with the key words."},{"term":"Describe","def":"Say what happens or what is done, step by step."},{"term":"Explain","def":"Give reasons using physics ideas (\"because… so…\")."},{"term":"Calculate","def":"Work out a numerical answer, showing working and units."},{"term":"Determine","def":"Find a value, often from a graph or data, showing the method."},{"term":"Deduce","def":"Draw a conclusion from the information given or worked out."},{"term":"Sketch","def":"A quick graph or diagram showing shape and key features, not to scale."},{"term":"Plot","def":"Mark points accurately on a grid using a chosen scale."},{"term":"Suggest","def":"Use physics to propose a sensible answer; more than one may be correct."},{"term":"Precaution","def":"A step taken to make readings more accurate or reliable, specific to the experiment."},{"term":"Mark scheme","def":"The list of points the examiner gives marks for; about one point per mark."}],"learn":{"notes":[{"type":"p","text":"Paper 02 rewards **the right words, in the right amount, with working shown**. Two students with the same physics knowledge can be a whole grade apart because of technique. This unit gives you the rules."},{"type":"h","text":"1. Command words — what is the examiner asking for?"},{"type":"table","headers":["Command word","What you must do","Example answer style"],"rows":[["**State / Name / List**","A short answer. No explanation needed.","\"State the unit of power.\" → watt (W)"],["**Define**","Give the exact meaning, in words, of a term. Include the key words.","\"Power is the rate of doing work / energy transferred per second.\""],["**Describe**","Say what happens or what you would do, step by step. For an experiment: diagram, method, measurements, precautions.","Numbered steps; say what you measure and with what instrument"],["**Explain**","Give the REASON — use physics ideas. \"Because…, so…\".","Link cause to effect; one point per mark"],["**Calculate**","Work out a number. Show formula, substitution and answer with unit.","⟪P=IV=0.50\\times 6.0=3.0\\,\\mathrm{W}⟫"],["**Determine**","Find a value, often from a graph or data, showing how.","Gradient with triangle shown on the graph"],["**Deduce**","Reach a conclusion from information you have been given or worked out.","\"The line passes through the origin, so ⟪V\\propto I⟫.\""],["**Sketch**","A quick graph/diagram showing the SHAPE and key features (labelled axes, origin). No exact scale.","Curve shape + axis labels"],["**Draw / Plot**","Accurate: use a ruler, a scale and correct plotted points.","Graph on grid; ruled ray diagram"],["**Suggest**","Use your physics to give a sensible idea — there may be several right answers.","\"Insulate the block to reduce heat loss.\""],["**Compare / Distinguish**","Give a point about BOTH things — the similarity or the difference.","\"α is stopped by paper, but β passes through paper.\""]]},{"type":"tip","text":"The number in brackets is your guide: **[1] = one point, [3] = three separate points or steps.** For a 3-mark \"explain\", write three linked facts. For a 3-mark calculation: formula (1), substitution (1), answer with unit (1).","label":"MARK-PER-POINT"},{"type":"h","text":"2. Showing working — the three-line method"},{"type":"formula","text":"Formula → Substitute (with units converted) → Answer + unit","where":["Line 1: write the formula in symbols, e.g. ⟪Q=mc\\Delta \\theta⟫","Line 2: put in the numbers, already converted to SI (g → kg, min → s, kW → W)","Line 3: the answer, to 2 or 3 significant figures, with its unit"],"label":"EVERY CALCULATION"},{"type":"remember","text":"If part (i) is wrong but you USE that answer correctly in part (ii), the examiner usually gives you the marks for (ii). This only works if your working is visible. A bare wrong answer earns nothing.","label":"ERROR CARRIED FORWARD (ECF)"},{"type":"warn","text":"Writing only the final number. If it is right you may get full marks — but if it is wrong you get **zero**, because the examiner cannot see the method marks you earned."},{"type":"h","text":"3. Significant figures and units"},{"type":"bullets","items":["Give your answer to the **same number of significant figures as the data** (usually 2 or 3). 4.0 m s^−1^, not 4 or 4.0000.","Do not round in the middle of a calculation — keep the full calculator value, round only at the end.","Table headings: **quantity / unit**, e.g. current, I / A. Then the table contains numbers only.","A unit is part of the answer. \"12\" is not a resistance; \"12 Ω\" is."]},{"type":"h","text":"4. The data-analysis checklist (Question 1)"},{"type":"p","text":"Question 1 is worth 25 marks — a quarter of the paper. Most of its marks are for **skills**, not for remembering facts, so they are the most \"learnable\" marks on the paper."},{"type":"table","headers":["Skill","What gets the mark"],"rows":[["**S** — Scale","Easy scale (1, 2, 5 or 10 per big square). Points use **more than half** the grid in both directions. Not a scale of 3 or 7."],["**P** — Points","Each point within half a small square. Small × or ⊙. Check each one twice."],["**L** — Line","One thin ruled line of best fit (or smooth curve). Points balanced either side. Never dot-to-dot."],["**A** — Axes","Both axes labelled with quantity and unit: \"current, I / A\". The variable you changed goes on the x-axis — unless the question says \"plot V against I\" (then V is up the side)."],["**T** — Title","\"Graph of V against I\" (the y-quantity first)."],["Gradient","Large triangle (more than half the line); read points ON THE LINE; show Δy and Δx; give the unit (y-unit ÷ x-unit)."],["Reading off","Draw dashed construction lines from the axis to the line and across — the examiner needs to see them."],["Anomalous point","Circle it, ignore it for the line, and suggest a cause (misreading, wire heated up)."],["Precautions","Specific to THIS experiment, e.g. switch off between readings; read meters at eye level (avoid parallax); repeat and average."]]},{"type":"img","src":"img/week13/model_graph","alt":"A model graph: sensible scale, labelled axes, best-fit line, anomalous point circled, large gradient triangle and construction lines for a read-off","caption":"A model graph: sensible scale, labelled axes, best-fit line, anomalous point circled, large gradient triangle and construction lines for a read-off","width":5.4,"w":1174,"h":854},{"type":"p","text":"From this graph: gradient ⟪=10.0\\,\\mathrm{cm}\\div 5.0\\,\\mathrm{N}=\\boldsymbol{2.0\\,\\mathrm{cm}\\,\\mathrm{N}^{-1}}⟫. At a load of 3.5 N, the extension read off the line is **7.0 cm**."},{"type":"h","text":"5. Extended-response answers (Questions 4–6)"},{"type":"bullets","items":["Spend 30 seconds planning: jot the key words in the margin before you write.","Use the physics words the mark scheme looks for (e.g. *electrons transferred*, *upthrust*, *latent heat*, *nucleus*).","Diagrams count: a labelled diagram can earn marks that words would take a paragraph to earn. Label every part.","\"Describe an experiment\" structure: **labelled diagram → method (numbered steps, what you measure and with what) → results (table/graph) → conclusion → one precaution.**","Write in short sentences. One idea per sentence is easier for you and for the examiner."]},{"type":"h","text":"6. Time"},{"type":"p","text":"2 h 30 min for 100 marks ≈ **1½ minutes per mark**. A 15-mark question gets about 20–22 minutes; Question 1 gets about 35 minutes. See the timing plan on the cover page."},{"type":"tip","text":"If you are stuck for more than 2 minutes on one part, leave a gap, put a star in the margin and move on. Come back at the end."}],"examples":[{"id":"week13.13.2.e1","title":"Turning a 1-mark answer into a 3-mark answer","question":"\"Explain why a metal spoon feels colder than a plastic spoon, although both are at room temperature. [3 marks]\"","steps":[{"label":"1-mark answer (weak)","text":"\"Metal is a good conductor.\" — one point only."},{"label":"Point 1","text":"Your hand is warmer than the spoon, so thermal energy flows from your hand to the spoon."},{"label":"Point 2","text":"Metal is a good conductor of heat; plastic is a poor conductor (insulator)."},{"label":"Point 3","text":"So the metal conducts energy away from your hand faster, and your hand loses heat faster — it feels colder."}],"answer":"Three linked points: direction of heat flow (1), conductor vs insulator (1), faster rate of energy loss from the hand (1)."},{"id":"week13.13.2.e2","title":"Earning every calculation mark","question":"A 0.50 kg ball is dropped from a height of 5.0 m. Ignoring air resistance, calculate its speed just before it hits the ground. [3 marks]","steps":[{"label":"Formula (1)","text":"Loss of PE = gain of KE: ⟪mgh=\\tfrac{1}{2}mv^{2}⟫, so ⟪v=\\sqrt{2gh}⟫"},{"label":"Substitute (1)","text":"⟪v=\\sqrt{2\\times 10\\times 5.0}=\\sqrt{100}⟫"},{"label":"Answer + unit (1)","text":"⟪v=10\\,\\mathrm{m}\\,\\mathrm{s}^{-1}⟫"}],"answer":"⟪v=10\\,\\mathrm{m}\\,\\mathrm{s}^{-1}⟫ — the mass cancels, so it was not needed."},{"id":"week13.13.2.e3","title":"\"Deduce\" from a graph","question":"A graph of V (y-axis) against I (x-axis) for a resistor is a straight line through the origin with gradient 8.0 V A^−1^. Deduce TWO things about the resistor. [2 marks]","steps":[{"label":"Straight line through origin","text":"V is directly proportional to I, so the resistor obeys Ohm's law (it is ohmic)."},{"label":"Gradient","text":"Gradient ⟪=V/I=R⟫, so its resistance is 8.0 Ω (and constant)."}],"answer":"Ohmic ⟪(V\\propto I)⟫ (1); resistance ⟪=8.0\\,\\Omega⟫ (1)."}]},"tryit":[{"id":"week13.13.2.p1","kind":"self","q":"Match each command word to what it asks for: (i) state, (ii) explain, (iii) sketch, (iv) calculate. Choose from: P — show the shape of a graph with labelled axes; Q — give a short fact only; R — work out a number showing working; S — give the reason using physics.","marks":4,"level":3,"lines":2,"scheme":"(i) Q (1); (ii) S (1); (iii) P (1); (iv) R (1).","points":[{"text":"(i) Q","marks":1},{"text":"(ii) S","marks":1},{"text":"(iii) P","marks":1},{"text":"(iv) R","marks":1}],"section":"try"},{"id":"week13.13.2.p2","kind":"self","q":"Define *specific latent heat of fusion*.","marks":2,"level":2,"lines":3,"scheme":"The energy (heat) needed to change 1 kg of a substance from solid to liquid (1) without a change in temperature (1).","points":[{"text":"The energy (heat) needed to change 1 kg of a substance from solid to liquid","marks":1},{"text":"without a change in temperature","marks":1}],"section":"try"}],"practice":[{"id":"week13.13.2.p3","kind":"self","q":"A current of 1.5 A flows through a 6.0 Ω resistor. Calculate (a) the p.d. across it and (b) the power. Show all working.","marks":4,"level":3,"lines":5,"scheme":"(a) ⟪V=IR=1.5\\times 6.0⟫ (1) ⟪=9.0\\,\\mathrm{V}⟫ (1). (b) ⟪P=IV=1.5\\times 9.0⟫ (1) ⟪=13.5\\,\\mathrm{W}⟫ (accept 14 W) (1).","points":[{"text":"(a) ⟪V=IR=1.5\\times 6.0⟫","marks":1},{"text":"⟪=9.0\\,\\mathrm{V}⟫","marks":1},{"text":"(b) ⟪P=IV=1.5\\times 9.0⟫","marks":1},{"text":"⟪=13.5\\,\\mathrm{W}⟫ (accept 14 W)","marks":1}],"section":"practice"},{"id":"week13.13.2.p4","kind":"self","q":"Explain why a steel ship floats although steel is denser than water.","marks":3,"level":2,"lines":4,"scheme":"The ship is hollow/contains air, so its average density is less than water (1); it displaces a large volume of water (1); the upthrust equals the weight of water displaced, which equals the weight of the ship (Archimedes' principle) (1).","points":[{"text":"The ship is hollow/contains air, so its average density is less than water","marks":1},{"text":"it displaces a large volume of water","marks":1},{"text":"the upthrust equals the weight of water displaced, which equals the weight of the ship (Archimedes' principle)","marks":1}],"section":"practice","hint":{"text":"Look back at Example 1 (Turning a 1-mark answer into a 3-mark answer). Start like this: 1-mark answer (weak): \"Metal is a good conductor.\" — one point only.","from":1}},{"id":"week13.13.2.p5","kind":"self","q":"A straight line on a graph of V / V against I / A passes through (0.10 A, 1.0 V) and (0.60 A, 6.6 V). Determine the gradient and state what it represents.","marks":3,"level":2,"lines":4,"scheme":"Gradient ⟪=(6.6-1.0)\\div (0.60-0.10)=5.6\\div 0.50⟫ (1) ⟪=11.2\\,\\Omega⟫ (1); it is the resistance of the conductor (1).","points":[{"text":"Gradient ⟪=(6.6-1.0)\\div (0.60-0.10)=5.6\\div 0.50⟫","marks":1},{"text":"⟪=11.2\\,\\Omega⟫","marks":1},{"text":"it is the resistance of the conductor","marks":1}],"section":"practice","hint":{"text":"Look back at Example 3 (\"Deduce\" from a graph). Start like this: Straight line through origin: V is directly proportional to I, so the resistor obeys Ohm's law (it is ohmic).","from":3}},{"id":"week13.13.2.p6","kind":"self","q":"Describe an experiment to show that sound needs a medium to travel through.","marks":4,"level":3,"lines":6,"scheme":"An electric bell is hung inside a bell jar connected to a vacuum pump (1); the bell is switched on and heard ringing (1); air is pumped out — the sound gets fainter until it can hardly be heard, though the hammer is still seen striking the gong (1); air is let back in and the sound returns, so sound needs a medium (air) (1).","points":[{"text":"An electric bell is hung inside a bell jar connected to a vacuum pump","marks":1},{"text":"the bell is switched on and heard ringing","marks":1},{"text":"air is pumped out — the sound gets fainter until it can hardly be heard, though the hammer is still seen striking the gong","marks":1},{"text":"air is let back in and the sound returns, so sound needs a medium (air)","marks":1}],"section":"practice"},{"id":"week13.13.2.p7","kind":"self","q":"Sketch the I–V graph for a filament lamp and explain its shape.","marks":3,"level":2,"lines":5,"scheme":"Sketch: curve through the origin, getting less steep as V increases (S-shape if negative values shown), axes labelled I and V (1). As the current increases the filament gets hotter (1), so its resistance increases and the current rises less for each extra volt (1).","points":[{"text":"Sketch: curve through the origin, getting less steep as V increases (S-shape if negative values shown), axes labelled I and V","marks":1},{"text":"As the current increases the filament gets hotter","marks":1},{"text":"so its resistance increases and the current rises less for each extra volt","marks":1}],"section":"practice"}],"exit":[{"id":"week13.13.2.p8","kind":"self","q":"Using about 1½ minutes per mark, how many minutes should you spend on (a) Question 1 (25 marks) and (b) a 15-mark question? What should you do if you reach the time limit?","marks":3,"level":2,"lines":3,"scheme":"(a) ≈ 35–38 min (accept 35) (1); (b) ≈ 20–22 min (1); leave a space, move to the next question and come back in the checking time (1).","points":[{"text":"(a) ≈ 35–38 min (accept 35)","marks":1},{"text":"(b) ≈ 20–22 min","marks":1},{"text":"leave a space, move to the next question and come back in the checking time","marks":1}],"section":"exit"},{"id":"week13.13.2.p9","kind":"self","q":"A student's results table has the heading \"Current (amps)\" and the values 0.1, 0.20, 0.3, 0.400. State THREE things wrong with this table.","marks":3,"level":2,"lines":4,"scheme":"Heading should be quantity / unit, e.g. current, I / A (1); unit symbol should be A, not \"amps\" (1); values not given to a consistent number of decimal places — should be 0.10, 0.20, 0.30, 0.40 (1).","points":[{"text":"Heading should be quantity / unit, e.g. current, I / A","marks":1},{"text":"unit symbol should be A, not \"amps\"","marks":1},{"text":"values not given to a consistent number of decimal places — should be 0.10, 0.20, 0.30, 0.40","marks":1}],"section":"exit"}],"warmup":[{"id":"week13.13.2.w1","kind":"self","q":"A student's total on the mock is 47 out of 100. Use the grade guide to give his approximate grade, and state ONE thing he should do next.","marks":2,"level":2,"lines":3,"scheme":"Approximately Grade IV (1); any sensible action, e.g. drill one section per day / redo the worked examples / redo every question below 60% (1).","points":[{"text":"Approximately Grade IV","marks":1},{"text":"any sensible action, e.g. drill one section per day / redo the worked examples / redo every question below 60%","marks":1}],"section":"warmup","src":"week13.13.1.p3"},{"id":"week13.13.2.w2","kind":"num","q":"A student scored 11 out of 25 on Question 1. Calculate his percentage for that question.","marks":1,"level":1,"lines":2,"scheme":"⟪11\\div 25\\times 100=44\\%⟫ (1).","points":[{"text":"⟪11\\div 25\\times 100=44\\%⟫","marks":1}],"num":{"value":44,"sf":2,"unit":"%","unitTex":"\\%"},"section":"warmup","src":"week13.13.1.p2"},{"id":"week13.13.2.w3","kind":"self","q":"A student wrote \"The density of the block is 2700.\" The mass was in kg and the volume in m^3^. Write the answer so that it would get full marks, and give the error code.","marks":2,"level":2,"lines":2,"scheme":"Density ⟪=2700\\,\\mathrm{kg}\\,\\mathrm{m}^{-3}⟫ (unit needed) (1); error code U (1).","points":[{"text":"Density ⟪=2700\\,\\mathrm{kg}\\,\\mathrm{m}^{-3}⟫ (unit needed)","marks":1},{"text":"error code U","marks":1}],"section":"warmup","src":"week13.13.1.p4"}],"n":109},{"id":"week13.mock","kind":"mock","paper":"P02","minutes":150,"title":"Mock Paper 02 (Full Exam)","titleText":"Mock Paper 02 (Full Exam)","check":true,"rules":[{"type":"p","text":"Read this page BEFORE you start the mock. It is the cover page of your paper. In the real exam the cover page says almost exactly the same things — knowing them now saves you time on the day."},{"type":"h","text":"MOCK EXAMINATION — PHYSICS PAPER 02 (General Proficiency)"},{"type":"table","headers":["Item","Details"],"rows":[["Time allowed","**2 hours 30 minutes** (150 minutes)"],["Total marks","**100**"],["Number of questions","**SIX** — answer **ALL** of them. There is no choice."],["Section A (structured)","Question 1 — data analysis (25 marks); Questions 2 and 3 — structured (15 marks each)"],["Section B (extended response)","Questions 4, 5 and 6 — extended response (15 marks each)"],["Equipment","Black or blue pen; pencil, ruler, eraser, protractor; silent non-programmable calculator"],["Where to answer","In the spaces provided in this book. Draw graphs and diagrams in pencil."]]},{"type":"h","text":"Instructions to the candidate"},{"type":"steps","items":["Answer ALL questions. Write your answers in the spaces provided.","The marks for each part are shown in brackets, e.g. [3 marks]. Use them to judge how much to write: one mark ≈ one point or one step.","Show ALL your working in calculations. Marks are given for the method, not just the final answer.","Give units with every numerical answer.","Use ⟪g=10\\,\\mathrm{N}\\,\\mathrm{kg}^{-1}⟫ unless the question gives another value.","Graphs: label both axes with quantity and unit, choose a sensible scale and plot points with a small ×.","Do not use correction fluid. Cross out mistakes neatly with a single line."]},{"type":"h","text":"Mark allocation"},{"type":"table","headers":["Question","Type","Marks","Suggested time"],"rows":[["Reading time","Read the WHOLE paper; mark the easy parts","—","5 min"],["Q1","Data analysis (table, graph, gradient, practical)","25","35 min"],["Q2","Structured","15","20 min"],["Q3","Structured","15","20 min"],["Q4","Extended response","15","22 min"],["Q5","Extended response","15","22 min"],["Q6","Extended response","15","22 min"],["Checking","Units, blanks, significant figures","—","4 min"],["**Total**","","**100**","**150 min**"]]},{"type":"img","src":"img/week13/timing_plan","alt":"Timing plan — about 1½ minutes per mark. Write the clock time for each finish line on your question paper before you start.","caption":"Timing plan — about 1½ minutes per mark. Write the clock time for each finish line on your question paper before you start.","width":6,"w":1251,"h":354},{"type":"table","headers":["Finish this…","by (minutes)","My clock time"],"rows":[["Reading","5",""],["Question 1","40",""],["Question 2","60",""],["Question 3","80",""],["Question 4","102",""],["Question 5","124",""],["Question 6","146",""],["Checking","150",""]]},{"type":"warn","text":"1. **Never leave a part blank.** A sensible attempt can earn a method mark; a blank earns nothing. 2. **Do not over-run on one question.** If you reach the finish time, leave a space and move on. You can come back in the checking time.","label":"THE TWO RULES THAT COST THE MOST MARKS"},{"type":"remember","text":"Sit the mock in **one sitting**, with a timer, and **no notes**. A mock done in pieces with the book open tells you nothing about the real exam."}],"total":100,"questions":[{"id":"week13.mock.q1","kind":"multi","title":"SECTION A · Question 1 (data analysis)","total":25,"stem":["A student investigated how the potential difference, V, across a length of nichrome wire changes with the current, I, through it. The wire was kept at a constant temperature. Her results are shown in Table 1."],"stemBlocks":[{"type":"table","headers":["Current, I / A","0.10","0.20","0.30","0.40","0.50","0.60"],"rows":[["Potential difference, V / V","1.2","2.5","3.6","4.2","6.0","7.1"]]},{"type":"p","text":"*Table 1*"}],"parts":[{"id":"week13.mock.q1.a","kind":"self","q":"Draw a circuit diagram of the arrangement the student could use. Include a battery, a switch, a variable resistor, the wire, an ammeter and a voltmeter.","marks":4,"level":3,"img":{"src":"img/week13/q1_box","alt":"Draw a circuit diagram of the arrangement the student could use. Include a battery, a switch, a variable resistor, the wire, an ammeter and a voltmeter.","w":967,"h":454},"lines":0,"scheme":"Battery/cell and switch in a complete series loop with the wire (1); ammeter in SERIES with the wire (1); voltmeter in PARALLEL across the wire only (1); variable resistor (rheostat) in series, correct symbol (1). Correct symbols must be used for the marks.\n**Common errors:** voltmeter drawn in series; ammeter across the wire; lamp symbol used for the wire; gaps in the circuit.","points":[{"text":"Battery/cell and switch in a complete series loop with the wire","marks":1},{"text":"ammeter in SERIES with the wire","marks":1},{"text":"voltmeter in PARALLEL across the wire only","marks":1},{"text":"variable resistor (rheostat) in series, correct symbol. Correct symbols must be used for the marks.\n**Common errors:** voltmeter drawn in series; ammeter across the wire; lamp symbol used for the wire; gaps in the circuit","marks":1}],"label":"(a)"},{"id":"week13.mock.q1.b","kind":"self","q":"On the grid provided, plot a graph of V (y-axis) against I (x-axis). Draw the line of best fit.","marks":6,"level":3,"img":{"src":"img/week13/q1_grid","alt":"On the grid provided, plot a graph of V (y-axis) against I (x-axis). Draw the line of best fit.","w":1214,"h":1014},"lines":0,"scheme":"Suitable linear scale using more than half the grid on both axes, e.g. 0.1 A per big square and 1 V per big square (1); both axes labelled with quantity and unit, V / V and I / A (1); points plotted correctly within half a small square: all six (3), four or five (2), two or three (1); single thin ruled best-fit straight line through (or very near) the origin, ignoring the point at 0.40 A (1).\n**Common errors:** scale of 3 per square; axes swapped (I plotted up the side); line forced through the anomalous point; dot-to-dot line.","points":[{"text":"Suitable linear scale using more than half the grid on both axes, e.g. 0.1 A per big square and 1 V per big square","marks":1},{"text":"both axes labelled with quantity and unit, V / V and I / A","marks":1},{"text":"points plotted correctly within half a small square: all six","marks":3},{"text":"four or five","marks":2},{"text":"two or three","marks":1},{"text":"single thin ruled best-fit straight line through (or very near) the origin, ignoring the point at 0.40 A. **Common errors:** scale of 3 per square; axes swapped (I plotted up the side); line forced through the anomalous point; dot-to-dot line","marks":1}],"conf":"low","label":"(b)"},{"id":"week13.mock.q1.c","kind":"self","q":"Identify the anomalous reading and suggest ONE reason for it.","marks":2,"level":2,"lines":3,"scheme":"The reading at ⟪I=0.40\\,\\mathrm{A}\\ (V=4.2\\,\\mathrm{V})⟫ (1); any one: voltmeter/ammeter misread (e.g. parallax); value recorded wrongly — it should be about 4.8 V; loose connection at that moment (1).","points":[{"text":"The reading at ⟪I=0.40\\,\\mathrm{A}\\ (V=4.2\\,\\mathrm{V})⟫","marks":1},{"text":"any one: voltmeter/ammeter misread (e.g. parallax); value recorded wrongly — it should be about 4.8 V; loose connection at that moment","marks":1}],"label":"(c)"},{"id":"week13.mock.q1.d","kind":"self","q":"Determine the gradient of your line. Show clearly on your graph how you obtained it.","marks":4,"level":3,"lines":4,"scheme":"Large triangle drawn on the line, covering more than half its length (1); correct readings of Δy and Δx from the line, e.g. ⟪(7.2-1.2)\\div (0.60-0.10)⟫ (1); gradient ≈ 12 (accept 11.5 to 12.5) (1); unit V A^−1^ or Ω (1).\n**Common errors:** small triangle; using table values that are not on the line (especially the anomalous point); Δx/Δy upside down giving ≈ 0.083; no unit.","points":[{"text":"Large triangle drawn on the line, covering more than half its length","marks":1},{"text":"correct readings of Δy and Δx from the line, e.g. ⟪(7.2-1.2)\\div (0.60-0.10)⟫","marks":1},{"text":"gradient ≈ 12 (accept 11.5 to 12.5)","marks":1},{"text":"unit V A^−1^ or Ω. **Common errors:** small triangle; using table values that are not on the line (especially the anomalous point); Δx/Δy upside down giving ≈ 0.083; no unit","marks":1}],"label":"(d)"},{"id":"week13.mock.q1.e","kind":"self","q":"State what the gradient of the graph represents. Deduce whether the wire obeys Ohm's law, giving a reason.","marks":3,"level":2,"lines":4,"scheme":"The gradient ⟪(V\\div I)⟫ is the resistance of the wire (1); yes, it obeys Ohm's law / is ohmic (1); because the graph is a straight line through the origin, so V is directly proportional to I (resistance constant) (1).\n**Common error:** saying \"straight line\" without \"through the origin\".","points":[{"text":"The gradient ⟪(V\\div I)⟫ is the resistance of the wire","marks":1},{"text":"yes, it obeys Ohm's law / is ohmic","marks":1},{"text":"because the graph is a straight line through the origin, so V is directly proportional to I (resistance constant). **Common error:** saying \"straight line\" without \"through the origin\"","marks":1}],"label":"(e)"},{"id":"week13.mock.q1.f","kind":"self","q":"Use your graph to find the current in the wire when the potential difference is 5.0 V. Show on your graph how you obtained your answer.","marks":2,"level":2,"lines":2,"scheme":"Construction lines drawn from ⟪V=5.0\\,\\mathrm{V}⟫ across to the line and down to the I-axis (1); ⟪I\\approx 0.42\\,\\mathrm{A}⟫ (accept 0.40 to 0.43 A, consistent with the student's line) (1).","points":[{"text":"Construction lines drawn from ⟪V=5.0\\,\\mathrm{V}⟫ across to the line and down to the I-axis","marks":1},{"text":"⟪I\\approx 0.42\\,\\mathrm{A}⟫ (accept 0.40 to 0.43 A, consistent with the student's line)","marks":1}],"num":{"value":0.42,"sf":2,"unit":"A","unitTex":"\\mathrm{A}","min":0.4,"max":0.43},"label":"(f)","autoKind":"num"},{"id":"week13.mock.q1.g","kind":"self","q":"Calculate the power dissipated in the wire when the current is 0.50 A. Give your answer to an appropriate number of significant figures.","marks":2,"level":2,"lines":3,"scheme":"⟪P=IV=0.50\\times 6.0⟫ (1) = 3.0 W (2 s.f., with unit) (1).","points":[{"text":"⟪P=IV=0.50\\times 6.0⟫","marks":1},{"text":"= 3.0 W (2 s.f., with unit)","marks":1}],"label":"(g)"},{"id":"week13.mock.q1.h","kind":"self","q":"State TWO precautions the student should take to obtain reliable results in this experiment.","marks":2,"level":2,"lines":3,"scheme":"Any two (1 each): switch off between readings so the wire does not heat up (resistance stays constant); read the meters with the eye directly in line with the scale/pointer to avoid parallax; check the meters read zero before starting (zero error); repeat readings and take the average; keep the connections tight/clean.\n**Common errors (Q1 overall):** generic precautions not linked to this experiment (\"be careful\", \"do it again\"); running out of time on the graph — Q1 should be finished by minute 40.","points":[{"text":"Any two (1 each): switch off between readings so the wire does not heat up (resistance stays constant); read the meters with the eye directly in line with the scale/pointer to avoid parallax; check the meters read zero before starting (zero error); repeat readings and take the average; keep the connections tight/clean.\n**Common errors (Q1 overall):** generic precautions not linked to this experiment (\"be careful\", \"do it again\"); running out of time on the graph — Q1 should be finished by minute 40.","marks":2,"each":true}],"label":"(h)"}]},{"id":"week13.mock.q2","kind":"multi","title":"SECTION A · Question 2","total":15,"stem":["A student used a 48 W electric heater to heat a 1.0 kg block of aluminium. The heater was switched on for 5.0 minutes and the temperature of the block rose from 26 °C to 42 °C."],"stemBlocks":[],"parts":[{"id":"week13.mock.q2.a","kind":"self","q":"Define *specific heat capacity*.","marks":2,"level":2,"lines":3,"scheme":"The energy (heat) needed to raise the temperature of 1 kg of a substance (1) by 1 K (or 1 °C) (1).\n**Common error:** confusing it with heat capacity (missing \"1 kg\").","points":[{"text":"The energy (heat) needed to raise the temperature of 1 kg of a substance","marks":1},{"text":"by 1 K (or 1 °C). **Common error:** confusing it with heat capacity (missing \"1 kg\")","marks":1}],"label":"(a)"},{"id":"week13.mock.q2.b","kind":"self","q":"(i) Calculate the electrical energy supplied by the heater.","marks":2,"level":2,"lines":3,"scheme":"⟪E=Pt=48\\times (5.0\\times 60)=48\\times 300⟫ (1) ⟪=14\\,400\\,\\mathrm{J}\\ (1.44\\times 10^{4}\\,\\mathrm{J})⟫ (1).\n**Common error:** using ⟪t=5⟫ (minutes not converted to seconds) → 240 J.","points":[{"text":"⟪E=Pt=48\\times (5.0\\times 60)=48\\times 300⟫","marks":1},{"text":"⟪=14\\,400\\,\\mathrm{J}\\ (1.44\\times 10^{4}\\,\\mathrm{J})⟫. **Common error:** using ⟪t=5⟫ (minutes not converted to seconds) → 240 J","marks":1}],"num":{"value":14400,"sf":3,"unit":"J","unitTex":"\\mathrm{J}"},"label":"(b)","autoKind":"num"},{"id":"week13.mock.q2.x","kind":"self","q":"(ii) Assuming all this energy is absorbed by the block, calculate the specific heat capacity of aluminium.","marks":2,"level":2,"lines":4,"scheme":"⟪c=E\\div (m\\Delta \\theta )=14\\,400\\div (1.0\\times 16)⟫ (1) ⟪=900\\,\\mathrm{J}\\,\\mathrm{kg}^{-1}\\,\\mathrm{K}^{-1}⟫ (1) (ECF from (b)(i)).\n**Common error:** using 42 °C instead of the temperature RISE (16 °C).","points":[{"text":"⟪c=E\\div (m\\Delta \\theta )=14\\,400\\div (1.0\\times 16)⟫","marks":1},{"text":"= 900 J kg^−1^ K^−1^ (ECF from (b)(i)).\n**Common error:** using 42 °C instead of the temperature RISE (16 °C)","marks":1}],"label":""},{"id":"week13.mock.q2.x3","kind":"self","q":"(iii) In practice, some energy is lost to the surroundings. Explain how this affects the value of c calculated, and suggest ONE way to reduce this loss.","marks":2,"level":2,"lines":3,"scheme":"The temperature rise is smaller than it would be, so the calculated c is too HIGH (larger than the true value) (1); any one: wrap/lag the block in insulating material (cotton wool, polystyrene); put a lid/insulating mat underneath; put oil in the thermometer and heater holes for good thermal contact (1).","points":[{"text":"The temperature rise is smaller than it would be, so the calculated c is too HIGH (larger than the true value)","marks":1},{"text":"any one: wrap/lag the block in insulating material (cotton wool, polystyrene); put a lid/insulating mat underneath; put oil in the thermometer and heater holes for good thermal contact","marks":1}],"label":""},{"id":"week13.mock.q2.c","kind":"self","q":"Calculate the energy needed to melt 0.050 kg of ice at 0 °C. (Specific latent heat of fusion of ice ⟪=3.34\\times 10^{5}\\,\\mathrm{J}\\,\\mathrm{kg}^{-1}⟫.)","marks":2,"level":2,"lines":3,"scheme":"⟪E=ml=0.050\\times 3.34\\times 10^{5}⟫ (1) ⟪=1.67\\times 10^{4}\\,\\mathrm{J}\\ (16\\,700\\,\\mathrm{J})⟫ (1).","points":[{"text":"⟪E=ml=0.050\\times 3.34\\times 10^{5}⟫","marks":1},{"text":"⟪=1.67\\times 10^{4}\\,\\mathrm{J}\\ (16\\,700\\,\\mathrm{J})⟫","marks":1}],"num":{"value":16700,"sf":3,"unit":"J","unitTex":"\\mathrm{J}"},"label":"(c)","autoKind":"num"},{"id":"week13.mock.q2.d","kind":"self","q":"Use the kinetic theory to explain why the temperature of the ice stays at 0 °C while it is melting, even though energy is being supplied.","marks":2,"level":2,"lines":3,"scheme":"The energy is used to break the bonds / overcome the attractive forces between the molecules (1); the average kinetic energy of the molecules does not increase, so the temperature stays constant (1).","points":[{"text":"The energy is used to break the bonds / overcome the attractive forces between the molecules","marks":1},{"text":"the average kinetic energy of the molecules does not increase, so the temperature stays constant","marks":1}],"label":"(d)"},{"id":"week13.mock.q2.e","kind":"self","q":"The air in a car tyre is at a pressure of 200 kPa at 27 °C. After a long drive the temperature of the air is 57 °C. Assuming the volume of the tyre stays constant, calculate the new pressure.","marks":3,"level":2,"lines":4,"scheme":"Temperatures in kelvin: ⟪T_{1}=27+273=300\\,\\mathrm{K}⟫ and ⟪T_{2}=57+273=330\\,\\mathrm{K}⟫ (1); ⟪p_{1}/T_{1}=p_{2}/T_{2}\\rightarrow p_{2}=200\\times 330\\div 300⟫ (1) ⟪=220\\,\\mathrm{kPa}⟫ (1).\n**Common errors (Q2):** using °C in the gas law (gives 422 kPa); not converting minutes to seconds; vague kinetic-theory answers (\"the ice is busy melting\").","points":[{"text":"Temperatures in kelvin: ⟪T_{1}=27+273=300\\,\\mathrm{K}⟫ and ⟪T_{2}=57+273=330\\,\\mathrm{K}⟫","marks":1},{"text":"⟪p_{1}/T_{1}=p_{2}/T_{2}\\rightarrow p_{2}=200\\times 330\\div 300⟫","marks":1},{"text":"⟪=220\\,\\mathrm{kPa}⟫. **Common errors (Q2):** using °C in the gas law (gives 422 kPa); not converting minutes to seconds; vague kinetic-theory answers (\"the ice is busy melting\")","marks":1}],"num":{"value":220,"sf":2,"unit":"kPa","unitTex":"\\mathrm{kPa}"},"label":"(e)","autoKind":"num"}]},{"id":"week13.mock.q3","kind":"multi","title":"SECTION A · Question 3","total":15,"stem":["Figure 1 shows a wave travelling along a rope at one instant. The frequency of the wave is 5.0 Hz."],"stemBlocks":[{"type":"img","src":"img/week13/q3_wave","alt":"Figure 1","caption":"Figure 1","width":5.2,"w":1092,"h":554}],"parts":[{"id":"week13.mock.q3.a","kind":"self","q":"Use Figure 1 to state (i) the amplitude and (ii) the wavelength of the wave.","marks":2,"level":2,"lines":2,"scheme":"(i) Amplitude ⟪=3.0\\,\\mathrm{cm}⟫ (1); (ii) wavelength ⟪=0.80\\,\\mathrm{m}⟫ (1).\n**Common errors:** amplitude given as 6 cm (peak to trough); wavelength read as 0.40 m (half a wave).","points":[{"text":"(i) Amplitude ⟪=3.0\\,\\mathrm{cm}⟫","marks":1},{"text":"(ii) wavelength ⟪=0.80\\,\\mathrm{m}⟫. **Common errors:** amplitude given as 6 cm (peak to trough); wavelength read as 0.40 m (half a wave)","marks":1}],"label":"(a)"},{"id":"week13.mock.q3.b","kind":"self","q":"Calculate (i) the speed of the wave and (ii) its period.","marks":3,"level":2,"lines":4,"scheme":"(i) ⟪v=f\\lambda =5.0\\times 0.80⟫ (1) ⟪=4.0\\,\\mathrm{m}\\,\\mathrm{s}^{-1}⟫ (1); (ii) ⟪T=1/f=1/5.0=0.20\\,\\mathrm{s}⟫ (1).","points":[{"text":"(i) ⟪v=f\\lambda =5.0\\times 0.80⟫","marks":1},{"text":"⟪=4.0\\,\\mathrm{m}\\,\\mathrm{s}^{-1}⟫","marks":1},{"text":"(ii) ⟪T=1/f=1/5.0=0.20\\,\\mathrm{s}⟫","marks":1}],"label":"(b)"},{"id":"week13.mock.q3.c","kind":"self","q":"The wave on the rope is transverse. Sound waves are longitudinal. State the difference between a transverse and a longitudinal wave.","marks":2,"level":2,"lines":3,"scheme":"Transverse: particles vibrate at right angles (perpendicular) to the direction the wave travels (1); longitudinal: particles vibrate parallel to (along) the direction the wave travels (1).","points":[{"text":"Transverse: particles vibrate at right angles (perpendicular) to the direction the wave travels","marks":1},{"text":"longitudinal: particles vibrate parallel to (along) the direction the wave travels","marks":1}],"label":"(c)"},{"id":"week13.mock.q3.d","kind":"self","q":"A ship sends a pulse of ultrasound straight down to the sea bed. The echo returns 0.40 s later. The speed of sound in sea water is 1500 m s^−1^. Calculate the depth of the sea.","marks":3,"level":2,"lines":4,"scheme":"Distance travelled ⟪=v\\times t=1500\\times 0.40=600\\,\\mathrm{m}⟫ (1); the pulse travels down AND back, so divide by 2 (1); depth ⟪=300\\,\\mathrm{m}⟫ (1).\n**Common error:** forgetting to halve → 600 m.","points":[{"text":"Distance travelled ⟪=v\\times t=1500\\times 0.40=600\\,\\mathrm{m}⟫","marks":1},{"text":"the pulse travels down AND back, so divide by 2","marks":1},{"text":"depth ⟪=300\\,\\mathrm{m}⟫. **Common error:** forgetting to halve → 600 m","marks":1}],"num":{"value":300,"sf":1,"unit":"m","unitTex":"\\mathrm{m}"},"label":"(d)","autoKind":"num"},{"id":"week13.mock.q3.e","kind":"self","q":"Figure 2 shows a ray of light entering a glass block. Calculate (i) the refractive index of the glass and (ii) the critical angle for the glass.","marks":4,"level":3,"img":{"src":"img/week13/q3_block","alt":"Figure 2 shows a ray of light entering a glass block. Calculate (i) the refractive index of the glass and (ii) the critical angle for the glass.","w":723,"h":694},"lines":5,"scheme":"(i) ⟪n=\\sin i\\div \\sin r=\\sin 40^{\\circ}\\div \\sin 25^{\\circ}⟫ (1) ⟪=0.643\\div 0.423=1.52⟫ (1); (ii) ⟪\\sin c=1/n=1/1.52=0.658⟫ (1); ⟪c=41^{\\circ}\\ (41.1^{\\circ})⟫ (1) (ECF from (i)).\n**Common errors:** calculator in radians; using angles measured from the surface; ⟪\\sin 40\\div \\sin 25⟫ calculated as ⟪40\\div 25=1.6⟫.","points":[{"text":"(i) ⟪n=\\sin i\\div \\sin r=\\sin 40^{\\circ}\\div \\sin 25^{\\circ}⟫","marks":1},{"text":"⟪=0.643\\div 0.423=1.52⟫","marks":1},{"text":"(ii) ⟪\\sin c=1/n=1/1.52=0.658⟫","marks":1},{"text":"c = 41° (41.1°) (ECF from (i)).\n**Common errors:** calculator in radians; using angles measured from the surface; ⟪\\sin 40\\div \\sin 25⟫ calculated as ⟪40\\div 25=1.6⟫","marks":1}],"label":"(e)"},{"id":"week13.mock.q3.f","kind":"self","q":"Name the type of electromagnetic wave used (i) in a TV remote control and (ii) to sterilise medical instruments.","marks":1,"level":1,"lines":2,"scheme":"(i) infrared AND (ii) gamma rays (accept ultraviolet for (ii)) — both needed for the mark (1).","points":[{"text":"(i) infrared AND (ii) gamma rays (accept ultraviolet for (ii)) — both needed for the mark","marks":1}],"label":"(f)"}]},{"id":"week13.mock.q4","kind":"multi","title":"SECTION B · Question 4 (extended response)","total":15,"stem":["Figure 3 shows car A, of mass 1200 kg, travelling at 15 m s^−1^ towards car B, of mass 800 kg, which is at rest. After the collision the two cars lock together and move off with the same velocity."],"stemBlocks":[{"type":"img","src":"img/week13/q4_cars","alt":"Figure 3","caption":"Figure 3","width":5.2,"w":1032,"h":494}],"parts":[{"id":"week13.mock.q4.a","kind":"self","q":"State the principle of conservation of linear momentum.","marks":2,"level":2,"lines":3,"scheme":"In a closed system / when no external force acts (1), the total momentum before a collision equals the total momentum after it (total momentum stays constant) (1).","points":[{"text":"In a closed system / when no external force acts","marks":1},{"text":"the total momentum before a collision equals the total momentum after it (total momentum stays constant)","marks":1}],"label":"(a)"},{"id":"week13.mock.q4.b","kind":"self","q":"Calculate the velocity of the two cars immediately after the collision.","marks":3,"level":2,"lines":4,"scheme":"Momentum before ⟪=1200\\times 15+800\\times 0=18\\,000\\,\\mathrm{kg}\\,\\mathrm{m}\\,\\mathrm{s}^{-1}⟫ (1); ⟪18\\,000=(1200+800)\\times v⟫ (1); ⟪v=18\\,000\\div 2000=9.0\\,\\mathrm{m}\\,\\mathrm{s}^{-1}⟫ (in the original direction of A) (1).\n**Common error:** using only 1200 kg after the collision (gives 15 m s^−1^) or adding the velocities.","points":[{"text":"Momentum before ⟪=1200\\times 15+800\\times 0=18\\,000\\,\\mathrm{kg}\\,\\mathrm{m}\\,\\mathrm{s}^{-1}⟫","marks":1},{"text":"⟪18\\,000=(1200+800)\\times v⟫","marks":1},{"text":"⟪v=18\\,000\\div 2000=9.0\\,\\mathrm{m}\\,\\mathrm{s}^{-1}⟫ (in the original direction of A). **Common error:** using only 1200 kg after the collision (gives 15 m s^−1^) or adding the velocities","marks":1}],"num":{"value":9,"sf":2,"unit":"m s^−1^","unitTex":"\\mathrm{m}\\,\\mathrm{s}^{-1}"},"conf":"low","label":"(b)","autoKind":"num"},{"id":"week13.mock.q4.c","kind":"self","q":"Calculate the kinetic energy of the cars (i) before and (ii) after the collision. Hence (iii) find the energy \"lost\" and state what happened to it.","marks":4,"level":3,"lines":6,"scheme":"(i) KE before ⟪=\\tfrac{1}{2}\\times 1200\\times 15^{2}=135\\,000\\,\\mathrm{J}⟫ (1); (ii) KE after ⟪=\\tfrac{1}{2}\\times 2000\\times 9.0^{2}=81\\,000\\,\\mathrm{J}⟫ (1); (iii) loss ⟪=135\\,000-81\\,000=54\\,000\\,\\mathrm{J}\\ (5.4\\times 10^{4}\\,\\mathrm{J})⟫ (1); converted to heat (thermal energy), sound and work done in bending/deforming the cars (any two) (1).\n**Common error:** forgetting to square v; saying energy is \"destroyed\".","points":[{"text":"(i) KE before ⟪=\\tfrac{1}{2}\\times 1200\\times 15^{2}=135\\,000\\,\\mathrm{J}⟫","marks":1},{"text":"(ii) KE after ⟪=\\tfrac{1}{2}\\times 2000\\times 9.0^{2}=81\\,000\\,\\mathrm{J}⟫","marks":1},{"text":"(iii) loss ⟪=135\\,000-81\\,000=54\\,000\\,\\mathrm{J}\\ (5.4\\times 10^{4}\\,\\mathrm{J})⟫","marks":1},{"text":"converted to heat (thermal energy), sound and work done in bending/deforming the cars (any two). **Common error:** forgetting to square v; saying energy is \"destroyed\"","marks":1}],"label":"(c)"},{"id":"week13.mock.q4.d","kind":"self","q":"The collision lasts 0.15 s. Calculate the average force exerted on car B during the collision.","marks":3,"level":2,"lines":4,"scheme":"⟪a=(v-u)\\div t=(9.0-0)\\div 0.15=60\\,\\mathrm{m}\\,\\mathrm{s}^{-2}⟫ (1); ⟪F=ma=800\\times 60⟫ (1) ⟪=48\\,000\\,\\mathrm{N}\\ (4.8\\times 10^{4}\\,\\mathrm{N})⟫ (1). (Alternative: F = change in momentum ÷ time ⟪=800\\times 9.0\\div 0.15⟫.)","points":[{"text":"⟪a=(v-u)\\div t=(9.0-0)\\div 0.15=60\\,\\mathrm{m}\\,\\mathrm{s}^{-2}⟫","marks":1},{"text":"⟪F=ma=800\\times 60⟫","marks":1},{"text":"⟪=48\\,000\\,\\mathrm{N}\\ (4.8\\times 10^{4}\\,\\mathrm{N})⟫ (Alternative: F = change in momentum ÷ time ⟪=800\\times 9.0\\div 0.15⟫.)","marks":1}],"label":"(d)"},{"id":"week13.mock.q4.e","kind":"self","q":"Use Newton's second law to explain how a seat belt that stretches slightly reduces injuries to a passenger in a crash.","marks":3,"level":2,"lines":5,"scheme":"The stretching increases the time taken for the passenger to stop (1); so the deceleration of the passenger is smaller (same change in velocity over a longer time) (1); by ⟪F=ma⟫ the force on the passenger is smaller, so fewer/less serious injuries (1).\n**Common errors (Q4):** saying the seat belt \"absorbs the force\"; no link to time or deceleration.","points":[{"text":"The stretching increases the time taken for the passenger to stop","marks":1},{"text":"so the deceleration of the passenger is smaller (same change in velocity over a longer time)","marks":1},{"text":"by ⟪F=ma⟫ the force on the passenger is smaller, so fewer/less serious injuries. **Common errors (Q4):** saying the seat belt \"absorbs the force\"; no link to time or deceleration","marks":1}],"label":"(e)"}]},{"id":"week13.mock.q5","kind":"multi","title":"SECTION B · Question 5 (extended response)","total":15,"stem":["An electric kettle is rated 2.4 kW, 240 V. It is connected to the mains using a three-pin plug with live, neutral and earth wires."],"stemBlocks":[],"parts":[{"id":"week13.mock.q5.a","kind":"self","q":"(i) Calculate the current in the kettle when it is working normally.","marks":2,"level":2,"lines":3,"scheme":"⟪I=P\\div V=2400\\div 240⟫ (1) ⟪=10\\,\\mathrm{A}⟫ (1).\n**Common error:** not converting 2.4 kW to 2400 W → 0.01 A.","points":[{"text":"⟪I=P\\div V=2400\\div 240⟫","marks":1},{"text":"⟪=10\\,\\mathrm{A}⟫. **Common error:** not converting 2.4 kW to 2400 W → 0.01 A","marks":1}],"num":{"value":10,"sf":1,"unit":"A","unitTex":"\\mathrm{A}"},"label":"(a)","autoKind":"num"},{"id":"week13.mock.q5.x","kind":"self","q":"(ii) Fuses of rating 3 A, 5 A and 13 A are available. Choose the most suitable fuse for the kettle and explain your choice.","marks":2,"level":2,"lines":3,"scheme":"13 A (1); it is the smallest rating that is just ABOVE the normal current of 10 A — a 3 A or 5 A fuse would blow at once, and a larger one would not protect the circuit (1).","points":[{"text":"13 A","marks":1},{"text":"it is the smallest rating that is just ABOVE the normal current of 10 A — a 3 A or 5 A fuse would blow at once, and a larger one would not protect the circuit","marks":1}],"label":""},{"id":"week13.mock.q5.x2","kind":"self","q":"(iii) The kettle is used for 15 minutes each day for 30 days. Electricity costs $0.80 per kWh. Calculate the cost of using the kettle.","marks":3,"level":2,"lines":4,"scheme":"Time ⟪=0.25\\,\\mathrm{h}\\times 30=7.5\\,\\mathrm{h}⟫ (1); energy ⟪=P\\times t=2.4\\,\\mathrm{kW}\\times 7.5\\,\\mathrm{h}=18\\,\\mathrm{kWh}⟫ (1); cost ⟪=18\\times \\$0.80=\\$14.40⟫ (1).\n**Common error:** using 15 h instead of 0.25 h, or watts instead of kilowatts.","points":[{"text":"Time ⟪=0.25\\,\\mathrm{h}\\times 30=7.5\\,\\mathrm{h}⟫","marks":1},{"text":"energy ⟪=P\\times t=2.4\\,\\mathrm{kW}\\times 7.5\\,\\mathrm{h}=18\\,\\mathrm{kWh}⟫","marks":1},{"text":"cost ⟪=18\\times \\$0.80=\\$14.40⟫. **Common error:** using 15 h instead of 0.25 h, or watts instead of kilowatts","marks":1}],"num":{"value":14.4,"sf":4,"unit":"","unitTex":""},"conf":"low","label":"","autoKind":"num"},{"id":"week13.mock.q5.b","kind":"self","q":"The kettle has a metal case. Explain how the earth wire and the fuse together protect the user if the live wire becomes loose and touches the case.","marks":3,"level":2,"lines":5,"scheme":"The earth wire connects the metal case to earth, a low-resistance path (1); a very large current flows from live through the case to earth (1); this current melts/blows the fuse in the live wire, disconnecting the supply, so the case does not stay live and the user is not electrocuted (1).","points":[{"text":"The earth wire connects the metal case to earth, a low-resistance path","marks":1},{"text":"a very large current flows from live through the case to earth","marks":1},{"text":"this current melts/blows the fuse in the live wire, disconnecting the supply, so the case does not stay live and the user is not electrocuted","marks":1}],"label":"(b)"},{"id":"week13.mock.q5.c","kind":"self","q":"Figure 4 shows a transformer used to supply 12 V from the 240 V mains. The primary coil has 2000 turns. Assuming the transformer is ideal, (i) calculate the number of turns on the secondary coil.","marks":2,"level":2,"img":{"src":"img/week13/q5_transformer","alt":"Figure 4 shows a transformer used to supply 12 V from the 240 V mains. The primary coil has 2000 turns. Assuming the transformer is ideal, (i) calculate the number of turns on the secondary coil.","w":941,"h":574},"lines":3,"scheme":"⟪V_{p}/V_{s}=N_{p}/N_{s}\\rightarrow N_{s}=N_{p}\\times V_{s}\\div V_{p}=2000\\times 12\\div 240⟫ (1) ⟪=100⟫ turns (1).","points":[{"text":"⟪V_{p}/V_{s}=N_{p}/N_{s}\\rightarrow N_{s}=N_{p}\\times V_{s}\\div V_{p}=2000\\times 12\\div 240⟫","marks":1},{"text":"⟪=100⟫ turns","marks":1}],"label":"(c)"},{"id":"week13.mock.q5.x5","kind":"self","q":"(ii) Explain how the transformer works, and why it would not work if the primary coil were connected to a d.c. supply.","marks":3,"level":2,"lines":5,"scheme":"The alternating current in the primary coil produces a changing (alternating) magnetic field/flux in the soft-iron core (1); this changing flux links the secondary coil and induces an alternating emf in it (electromagnetic induction) (1); d.c. gives a steady field that does not change, so no emf is induced in the secondary (1).\n**Common errors (Q5):** \"the current flows through the core to the secondary\"; fuse chosen as exactly 10 A or \"the biggest\"; not saying the fuse is in the live wire.","points":[{"text":"The alternating current in the primary coil produces a changing (alternating) magnetic field/flux in the soft-iron core","marks":1},{"text":"this changing flux links the secondary coil and induces an alternating emf in it (electromagnetic induction)","marks":1},{"text":"d.c. gives a steady field that does not change, so no emf is induced in the secondary. **Common errors (Q5):** \"the current flows through the core to the secondary\"; fuse chosen as exactly 10 A or \"the biggest\"; not saying the fuse is in the live wire","marks":1}],"label":""}]},{"id":"week13.mock.q6","kind":"multi","title":"SECTION B · Question 6 (extended response)","total":15,"stem":["This question is about the structure of the atom and radioactivity."],"stemBlocks":[],"parts":[{"id":"week13.mock.q6.a","kind":"self","q":"Describe the Geiger–Marsden (alpha-particle scattering) experiment. State what was observed and what each observation showed about the structure of the atom.","marks":4,"level":3,"lines":7,"scheme":"A beam of alpha particles was fired at a very thin gold foil (in a vacuum), with a detector moved around the foil (1); most alpha particles passed straight through — so the atom is mostly empty space (1); a few were deflected through large angles and a very small number bounced back (1); so the atom has a tiny, dense, positively charged nucleus that contains most of the mass (1).\n**Common error:** describing Thomson's plum-pudding model as the conclusion; saying electrons deflected the alpha particles.","points":[{"text":"A beam of alpha particles was fired at a very thin gold foil (in a vacuum), with a detector moved around the foil","marks":1},{"text":"most alpha particles passed straight through — so the atom is mostly empty space","marks":1},{"text":"a few were deflected through large angles and a very small number bounced back","marks":1},{"text":"so the atom has a tiny, dense, positively charged nucleus that contains most of the mass. **Common error:** describing Thomson's plum-pudding model as the conclusion; saying electrons deflected the alpha particles","marks":1}],"label":"(a)"},{"id":"week13.mock.q6.b","kind":"self","q":"Radium-226 decays by emitting an alpha particle: ⟪{}^{226}_{88}Ra\\rightarrow {}^{A}_{Z}Rn+{}^{4}_{2}⟫He. Find the values of A and Z.","marks":2,"level":2,"lines":3,"scheme":"⟪A=226-4=222⟫ (1); ⟪Z=88-2=86⟫ (1).","points":[{"text":"⟪A=226-4=222⟫","marks":1},{"text":"⟪Z=88-2=86⟫","marks":1}],"label":"(b)"},{"id":"week13.mock.q6.c","kind":"self","q":"Figure 5 shows how the activity of a radioactive sample changes with time. (i) Use the graph to find the half-life of the sample, showing your method on the graph.","marks":2,"level":2,"img":{"src":"img/week13/q6_decay","alt":"Figure 5 shows how the activity of a radioactive sample changes with time. (i) Use the graph to find the half-life of the sample, showing your method on the graph.","w":1094,"h":734},"lines":3,"scheme":"Shows a halving on the graph, e.g. 800 → 400 counts per minute, with construction lines (1); half-life ⟪=8\\,\\mathrm{days}⟫ (accept 7.5–8.5 days) (1).","points":[{"text":"Shows a halving on the graph, e.g. 800 → 400 counts per minute, with construction lines","marks":1},{"text":"half-life ⟪=8\\,\\mathrm{days}⟫ (accept 7.5–8.5 days)","marks":1}],"num":{"value":8,"sf":1,"unit":"days","unitTex":"\\mathrm{days}","min":7.5,"max":8.5},"label":"(c)","autoKind":"num"},{"id":"week13.mock.q6.x","kind":"self","q":"(ii) Calculate the activity of the sample 40 days after the start.","marks":2,"level":2,"lines":3,"scheme":"⟪40\\div 8=5⟫ half-lives (1); 800 → 400 → 200 → 100 → 50 → 25 counts per minute (1) (ECF from (c)(i)).\n**Common error:** dividing 800 by ⟪5\\ (=160)⟫ instead of halving five times.","points":[{"text":"⟪40\\div 8=5⟫ half-lives","marks":1},{"text":"800 → 400 → 200 → 100 → 50 → 25 counts per minute (ECF from (c)(i)).\n**Common error:** dividing 800 by ⟪5\\ (=160)⟫ instead of halving five times","marks":1}],"label":""},{"id":"week13.mock.q6.d","kind":"self","q":"Compare the penetrating powers of alpha, beta and gamma radiation. Hence state, with a reason, which radiation is used to monitor the thickness of paper in a paper mill.","marks":3,"level":2,"lines":5,"scheme":"Alpha is stopped by a sheet of paper / a few cm of air; beta by a few mm of aluminium; gamma is only reduced by thick lead/concrete (all three for 1) (1); beta is used (1); because the amount passing through changes measurably with small changes in paper thickness — alpha would be stopped completely and gamma would pass through almost unchanged (1).","points":[{"text":"Alpha is stopped by a sheet of paper / a few cm of air; beta by a few mm of aluminium; gamma is only reduced by thick lead/concrete (all three for 1)","marks":1},{"text":"beta is used","marks":1},{"text":"because the amount passing through changes measurably with small changes in paper thickness — alpha would be stopped completely and gamma would pass through almost unchanged","marks":1}],"label":"(d)"},{"id":"week13.mock.q6.e","kind":"self","q":"A Caribbean government is considering building a nuclear power station. Give ONE argument for and ONE argument against this.","marks":2,"level":2,"lines":4,"scheme":"For (any one): no carbon dioxide/greenhouse gases; large amount of energy from a small mass of fuel ⟪(E=mc^{2})⟫; reduces dependence on imported oil; reliable supply (1). Against (any one): radioactive waste stays dangerous for a very long time; risk of accidents/leaks, made worse by hurricanes or earthquakes in the region; very high building and decommissioning costs; small islands lack space/expertise (1).\n**Common errors (Q6):** mixing up mass number and atomic number; \"gamma is used because it is strongest\"; one-sided answer to (e).","points":[{"text":"For (any one): no carbon dioxide/greenhouse gases; large amount of energy from a small mass of fuel ⟪(E=mc^{2})⟫; reduces dependence on imported oil; reliable supply","marks":1},{"text":"Against (any one): radioactive waste stays dangerous for a very long time; risk of accidents/leaks, made worse by hurricanes or earthquakes in the region; very high building and decommissioning costs; small islands lack space/expertise. **Common errors (Q6):** mixing up mass number and atomic number; \"gamma is used because it is strongest\"; one-sided answer to (e)","marks":1}],"label":"(e)"}]}],"grades":[{"min":75,"max":100,"grade":"I","todo":"Polish: timing, precise wording, the hardest calculations"},{"min":60,"max":74,"grade":"II","todo":"Fix your top two error codes; drill your weakest section"},{"min":50,"max":59,"grade":"III","todo":"Secure the \"easy\" marks: definitions, units, graph skills"},{"min":40,"max":49,"grade":"IV","todo":"Drill one section per day; redo all worked examples"},{"min":30,"max":39,"grade":"V","todo":"Back to basics: formula card daily, every definition"},{"min":0,"max":29,"grade":"VI","todo":"Do not panic — a mock is practice. Follow the plan with your tutor"}],"n":110},{"id":"week13.13.1","kind":"unit","unit":"13.1","title":"How to Review Your Mock","titleText":"How to Review Your Mock","goals":[{"code":"A","text":"Section A — Mechanics: scientific method and measurement, graph skills, vectors, forces and moments, motion and momentum, energy and power, hydrostatics"},{"code":"B","text":"Section B — Thermal physics and kinetic theory: temperature, gas laws, specific heat capacity, latent heat, heat transfer"},{"code":"C","text":"Section C — Waves and optics: wave properties, sound, the electromagnetic spectrum, reflection, refraction, total internal reflection, lenses"},{"code":"D","text":"Section D — Electricity and magnetism: static charge, current and circuits, mains electricity, electronics, magnetism, electromagnetism and transformers"},{"code":"E","text":"Section E — The physics of the atom: models of the atom, atomic structure, radioactivity, half-life, nuclear energy"}],"codes":["A","B","C","D","E"],"words":[{"term":"State","def":"Give a short answer with no explanation."},{"term":"Explain","def":"Give reasons using physics ideas (\"because… so…\")."},{"term":"Calculate","def":"Work out a numerical answer, showing working and units."},{"term":"Mark scheme","def":"The list of points the examiner gives marks for; about one point per mark."}],"learn":{"notes":[{"type":"p","text":"Your tutor marks the paper. **Your** job is the review. Students who review properly gain far more from a mock than students who just look at the score. The score tells you *where you are*; the review tells you *how to move up*."},{"type":"h","text":"The five-step review method"},{"type":"steps","items":["**Score it.** Fill in the score table below for each question. Work out the percentage for each question.","**Label every lost mark.** Next to each mark you lost, write an error code (K, M, A, U, R, D, G or T — see the table).","**Count the codes.** Fill in the error tally. The biggest number is your biggest problem.","**Correct it.** Re-write every wrong answer in full, in a different colour pen, using the mark scheme as a guide. Do not just copy — write it the way you would in the exam.","**Redo it.** Seven days later, cover your corrections and redo every question where you scored less than 60%. If you now get it right, the mark is yours."]},{"type":"h","text":"Error codes — why was the mark lost?"},{"type":"table","headers":["Code","Type of error","What it looks like","How to fix it"],"rows":[["**K**","Knowledge","Did not know the definition, fact or law","Flash cards; re-read the notes for that week"],["**M**","Method","Wrong formula or wrong approach","Redo the worked examples in that unit"],["**A**","Arithmetic","Right method, calculator slip","Write every step; check the answer is sensible"],["**U**","Units","No unit, wrong unit, or no conversion (g → kg, min → s, W → kW)","Convert BEFORE substituting; write the unit every time"],["**R**","Read wrongly","Answered a different question; missed \"TWO\" or \"explain\"","Underline the command word and the number of points"],["**D**","Detail","\"Explain\" answered with one word; too few points for the marks","1 mark ≈ 1 point: count your points"],["**G**","Graph skills","Bad scale, no labels, small triangle, dot-to-dot line","Use the SPLAT checklist (Unit 13.2)"],["**T**","Time","Ran out of time; left parts blank","Follow the timing plan; never get stuck"]]},{"type":"h","text":"My mock score table"},{"type":"table","headers":["Question","Main topic","Out of","My mark","%","Error codes"],"rows":[["Q1","Data analysis: V–I of a wire (⟪D+A⟫ skills)","25","","",""],["Q2","Thermal physics (B)","15","","",""],["Q3","Waves, sound, light (C)","15","","",""],["Q4","Momentum and energy (A)","15","","",""],["Q5","Mains electricity and transformers (D)","15","","",""],["Q6","The atom and radioactivity (E)","15","","",""],["**Total**","","**100**","","",""]]},{"type":"formula","tex":"\\%=(\\text{my mark }\\div \\text{ marks available})\\times 100","where":["Example: 9 out of ⟪15\\rightarrow 9\\div 15\\times 100=60\\%⟫"],"label":"PERCENTAGE FOR A QUESTION"},{"type":"h","text":"Error tally"},{"type":"table","headers":["Code","K","M","A","U","R","D","G","T"],"rows":[["Marks lost","","","","","","","",""]]},{"type":"h","text":"What does my score mean? (approximate grade guide)"},{"type":"table","headers":["Paper 02 mock %","Approximate grade","What to do next"],"rows":[["75–100","I","Polish: timing, precise wording, the hardest calculations"],["60–74","II","Fix your top two error codes; drill your weakest section"],["50–59","III","Secure the \"easy\" marks: definitions, units, graph skills"],["40–49","IV","Drill one section per day; redo all worked examples"],["30–39","V","Back to basics: formula card daily, every definition"],["0–29","VI","Do not panic — a mock is practice. Follow the plan with your tutor"]]},{"type":"warn","text":"This guide is only a rough estimate. The real grade boundaries are set by CXC each year, and your final grade also uses Paper 01 (MCQ) and the SBA. Use it to see the trend, not as a promise.","label":"IMPORTANT"},{"type":"h","text":"Turning errors into a revision plan"},{"type":"p","text":"Every question in the mock links to a book you already have. Go back to that book — do not try to learn from the mark scheme alone."},{"type":"table","headers":["Mock question","Re-read and redo practice from"],"rows":[["Q1 (data analysis)","Week 1 (graph skills, Unit 1.2) and Week 9 / 1-to-1 Session 2 (Ohm's law, I–V graphs)"],["Q2 (thermal)","Week 5 (specific heat, latent heat) and Week 6 (gas laws, kinetic theory)"],["Q3 (waves and light)","Week 7 (waves, sound, EM spectrum) and Week 8 (refraction, critical angle)"],["Q4 (momentum and energy)","Week 3 (Newton's laws, momentum) and Week 4 (energy)"],["Q5 (mains and transformers)","Week 10 / 1-to-1 Session 3 (mains, fuses) and Week 11 (transformers)"],["Q6 (the atom)","Week 12 (the physics of the atom)"]]},{"type":"tip","text":"Any question where you scored **below 60%** goes on your redo list. Redo it **without notes** 7 days later. Most students gain 10–15 marks between a first mock and the real exam just by doing this.","label":"THE 60% RULE"},{"type":"remember","text":"A mark you lost and now understand is worth more than a mark you got by luck. Be honest with the error codes — nobody else sees them."}],"examples":[{"id":"week13.13.1.e1","title":"Labelling a lost mark","question":"A student answered: \"Calculate the energy, in kWh, used by a 1500 W heater switched on for 3 hours. [3 marks]\" with \"⟪E=P\\times t=1500\\times 3=4500\\,\\mathrm{kWh}⟫\". How many marks did he get, what is the error code, and what is the correct answer?","steps":[{"label":"Formula mark","text":"⟪E=P\\times t⟫ is correct → **1 mark**."},{"label":"Substitution mark","text":"Power must be in **kW** to get kWh: ⟪1500\\,\\mathrm{W}=1.5\\,\\mathrm{kW}⟫. He used 1500 → **0**."},{"label":"Answer mark","text":"4500 kWh is wrong → **0**. Code: **U** (unit conversion)."},{"label":"Correction","text":"⟪E=P\\times t=1.5\\,\\mathrm{kW}\\times 3\\,\\mathrm{h}=\\boldsymbol{4.5\\,\\mathrm{kWh}}⟫."}],"answer":"1 mark out of 3; error code U; correct answer 4.5 kWh"},{"id":"week13.13.1.e2","title":"From score to plan","question":"A student scored Q1 14/25, Q2 9/15, Q3 6/15, Q4 8/15, Q5 10/15, Q6 5/15. Find his total, his approximate grade and his top two priorities.","steps":[{"label":"Total","text":"⟪14+9+6+8+10+5=\\boldsymbol{52}⟫** out of **⟪\\boldsymbol{100}=52\\%⟫."},{"label":"Grade","text":"52% is in the 50–59 band → approximately **Grade III**."},{"label":"Percentages","text":"Q1 56%, Q2 60%, Q3 40%, Q4 53%, Q5 67%, Q6 33%."},{"label":"Below 60%","text":"Q6 (33%), Q3 (40%), Q4 (53%), Q1 (56%) go on the redo list. Lowest two: Q6 and Q3."}],"answer":"52% ≈ Grade III; priorities: Q6 (the atom — Week 12) and Q3 (waves and light — Weeks 7–8)"},{"id":"week13.13.1.e3","title":"Correcting a \"detail\" error","question":"\"Explain why the temperature of ice stays at 0 °C while it is melting. [2 marks]\" The student wrote: \"Because it is melting.\" Mark it and write a full-mark correction.","steps":[{"label":"Mark","text":"0 out of 2. It repeats the question. Code: **D** (detail)."},{"label":"Point 1","text":"The energy supplied is used to **break the bonds / overcome the forces between the molecules** (latent heat)."},{"label":"Point 2","text":"It does **not increase the kinetic energy** of the molecules, so the temperature does not rise."}],"answer":"Two separate physics points = two marks. Count your points against the marks."}]},"tryit":[{"id":"week13.13.1.p1","kind":"self","q":"Give the error code (K, M, A, U, R, D, G or T) for each of these lost marks. (i) Wrote \"density ⟪=2.7⟫\" with no unit. (ii) Used ⟪V=I/R⟫. (iii) Gave one reason when the question asked for TWO. (iv) Left Q6 blank because time ran out.","marks":4,"level":3,"lines":4,"scheme":"(i) U (1); (ii) M (or K) (1); (iii) R (1); (iv) T (1).","points":[{"text":"(i) U","marks":1},{"text":"(ii) M (or K)","marks":1},{"text":"(iii) R","marks":1},{"text":"(iv) T","marks":1}],"section":"try","hint":{"text":"Look back at Example 1 (Labelling a lost mark). Start like this: Formula mark: ⟪E=P\\times t⟫ is correct → **1 mark**.","from":1}},{"id":"week13.13.1.p2","kind":"num","q":"A student scored 11 out of 25 on Question 1. Calculate his percentage for that question.","marks":1,"level":1,"lines":2,"scheme":"⟪11\\div 25\\times 100=44\\%⟫ (1).","points":[{"text":"⟪11\\div 25\\times 100=44\\%⟫","marks":1}],"num":{"value":44,"sf":2,"unit":"%","unitTex":"\\%"},"section":"try","hint":{"text":"Look back at Example 1 (Labelling a lost mark). Start like this: Formula mark: ⟪E=P\\times t⟫ is correct → **1 mark**.","from":1}}],"practice":[{"id":"week13.13.1.p3","kind":"self","q":"A student's total on the mock is 47 out of 100. Use the grade guide to give his approximate grade, and state ONE thing he should do next.","marks":2,"level":2,"lines":3,"scheme":"Approximately Grade IV (1); any sensible action, e.g. drill one section per day / redo the worked examples / redo every question below 60% (1).","points":[{"text":"Approximately Grade IV","marks":1},{"text":"any sensible action, e.g. drill one section per day / redo the worked examples / redo every question below 60%","marks":1}],"section":"practice","hint":{"text":"Look back at Example 2 (From score to plan). Start like this: Total: ⟪14+9+6+8+10+5=\\boldsymbol{52}⟫** out of **⟪\\boldsymbol{100}=52\\%⟫.","from":2}},{"id":"week13.13.1.p4","kind":"self","q":"A student wrote \"The density of the block is 2700.\" The mass was in kg and the volume in m^3^. Write the answer so that it would get full marks, and give the error code.","marks":2,"level":2,"lines":2,"scheme":"Density ⟪=2700\\,\\mathrm{kg}\\,\\mathrm{m}^{-3}⟫ (unit needed) (1); error code U (1).","points":[{"text":"Density ⟪=2700\\,\\mathrm{kg}\\,\\mathrm{m}^{-3}⟫ (unit needed)","marks":1},{"text":"error code U","marks":1}],"section":"practice","hint":{"text":"Look back at Example 3 (Correcting a \"detail\" error). Start like this: Mark: 0 out of 2. It repeats the question. Code: **D** (detail).","from":3}},{"id":"week13.13.1.p5","kind":"self","q":"Question: \"Explain why the fuse is placed in the live wire. [2 marks]\" A student wrote \"To protect the appliance.\" Re-write the answer for 2 marks.","marks":2,"level":2,"lines":3,"scheme":"If a fault causes too large a current, the fuse melts/blows and breaks the circuit (1); because it is in the live wire, the appliance is disconnected from the high voltage, so the casing/wires are no longer live and cannot shock the user (1).","points":[{"text":"If a fault causes too large a current, the fuse melts/blows and breaks the circuit","marks":1},{"text":"because it is in the live wire, the appliance is disconnected from the high voltage, so the casing/wires are no longer live and cannot shock the user","marks":1}],"section":"practice","hint":{"text":"Look back at Example 3 (Correcting a \"detail\" error). Start like this: Mark: 0 out of 2. It repeats the question. Code: **D** (detail).","from":3}},{"id":"week13.13.1.p6","kind":"self","q":"A student drew a gradient triangle 1 cm wide on a graph whose line was 14 cm long. He lost a mark. Explain why, and give the error code.","marks":2,"level":2,"lines":3,"scheme":"A small triangle gives a large (percentage) error in reading Δx and Δy, so the gradient is inaccurate; the triangle should cover more than half the line (1); code G (1).","points":[{"text":"A small triangle gives a large (percentage) error in reading Δx and Δy, so the gradient is inaccurate; the triangle should cover more than half the line","marks":1},{"text":"code G","marks":1}],"section":"practice","hint":{"text":"Look back at Example 1 (Labelling a lost mark). Start like this: Formula mark: ⟪E=P\\times t⟫ is correct → **1 mark**.","from":1}}],"exit":[{"id":"week13.13.1.p7","kind":"self","q":"A student scored Q1 18/25, Q2 6/15, Q3 11/15, Q4 7/15, Q5 12/15, Q6 9/15. (a) Find his total and approximate grade. (b) Which questions go on his redo list (below 60%)? (c) Which workbook weeks should he re-read first?","marks":4,"level":3,"lines":5,"scheme":"(a) ⟪18+6+11+7+12+9=63⟫ (1) → approximately Grade II (1). (b) Q2 (40%) and Q4 (47%) (1). (c) Weeks 5–6 for thermal physics and Weeks 3–4 for momentum/energy (1).","points":[{"text":"(a) ⟪18+6+11+7+12+9=63⟫","marks":1},{"text":"→ approximately Grade II","marks":1},{"text":"(b) Q2 (40%) and Q4 (47%)","marks":1},{"text":"(c) Weeks 5–6 for thermal physics and Weeks 3–4 for momentum/energy","marks":1}],"section":"exit"},{"id":"week13.13.1.p8","kind":"self","q":"After your mock is marked: fill in YOUR score table and error tally above. Then write your three biggest error codes and one action for each.","marks":3,"level":2,"lines":5,"scheme":"Personal answer — tutor checks that (1) each code is genuine (taken from the marked script), (1) each action is specific (a named week/unit or skill), and (1) a redo date 7 days later is written.","points":[{"text":"Personal answer — tutor checks that","marks":1},{"text":"each code is genuine (taken from the marked script)","marks":1},{"text":"each action is specific (a named week/unit or skill), and. a redo date 7 days later is written","marks":1}],"section":"exit"}],"warmup":[{"id":"week13.13.1.w1","kind":"self","q":"What does each letter of SPLAT stand for?","marks":1,"level":1,"scheme":"Scale, Points, Labels, Line, Title.","points":[{"text":"Scale, Points, Labels, Line, Title.","marks":1}],"section":"warmup","src":"week14.r1"},{"id":"week13.13.1.w2","kind":"self","q":"A graph of V against I is a straight line through the origin. What does the gradient give, and what does the shape tell you?","marks":1,"level":1,"scheme":"Gradient = resistance; V is directly proportional to I (ohmic conductor, constant resistance).","points":[{"text":"Gradient = resistance; V is directly proportional to I (ohmic conductor, constant resistance).","marks":1}],"section":"warmup","src":"week14.r2"},{"id":"week13.13.1.w3","kind":"self","q":"State the critical-angle formula and find c for ⟪n=1.50⟫.","marks":1,"level":1,"scheme":"⟪\\sin c=1/n⟫; ⟪c=41.8^{\\circ}\\approx 42^{\\circ}⟫.","points":[{"text":"⟪\\sin c=1/n⟫; ⟪c=41.8^{\\circ}\\approx 42^{\\circ}⟫.","marks":1}],"section":"warmup","src":"week14.r3"},{"id":"week13.13.1.w4","kind":"self","q":"How long should you spend on Question 1 of Paper 02, and why?","marks":1,"level":1,"scheme":"About 40 minutes — it is worth 25 marks, at about 1½ minutes per mark.","points":[{"text":"About 40 minutes — it is worth 25 marks, at about 1½ minutes per mark.","marks":1}],"section":"warmup","src":"week14.r4"},{"id":"week13.13.1.w5","kind":"self","q":"Give the three key points for 'Explain why the pressure of a heated gas in a sealed container increases'.","marks":1,"level":1,"scheme":"Molecules gain KE / move faster; hit the walls more often; with greater force — so force per unit area (pressure) increases.","points":[{"text":"Molecules gain KE / move faster; hit the walls more often; with greater force — so force per unit area (pressure) increases.","marks":1}],"section":"warmup","src":"week14.r5"}],"n":111}]};
